from parsing import parse_kv

def test_kv_spaces():
    assert parse_kv(" a = 1 , b = 2 ") == {"a": "1", "b": "2"}

def test_kv_empty_segments():
    assert parse_kv("a=1,,b=2") == {"a": "1", "b": "2"}

def test_kv_value_with_equal():
    assert parse_kv("a=b=c") == {"a": "b=c"}
